int main(int argc, char** argv) {
    lb_core_13process_start();
    lb_memory_startup();
    lb_init_runtime_globals();
    lb_span args = lb_core_13raw_arguments(argc, argv);
    lb_r_i32 r = lb_main(args);
    if (r.failed) { fprintf(stderr, "error %d: %.*s\n", r.error.code, (int)r.error.message.length, r.error.message.data); }
    int result = r.failed ? 1 : (int)r.value;
    return result;
}